alue="">Aucun</option><?php foreach(App\Core\DB::all('SELECT id,number,title FROM tickets WHERE project_id=? AND archived=0 ORDER BY number DESC LIMIT 500',[$project['id']]) as $t): ?><option value="<?= (int)$t['id'] ?>"><?= e($project['project_key'].'-'.$t['number'].' · '.$t['title']) ?></option><?php endforeach; ?></select></label></div><details><summary>Plus de détails</summary><div class="stack details-content"><div class="inline-fields"><label>Date de début<input type="date" name="start_date"></label><label>Date d’échéance<input type="date" name="due_date"></label></div><label>Étiquettes<input name="labels" placeholder="web, expérience client, magasin"></label><label class="check-label"><input type="checkbox" name="flagged" value="1">Signaler comme bloqué</label></div></details><footer class="dialog-footer"><label class="check-label"><input type="checkbox" name="another" value="1">En créer un autre</label><button class="button primary"><?= icon('plus') ?>Créer le ticket</button></footer></form></dialog>
